import { readFile, writeFile, mkdir } from "node:fs/promises";
const root = new URL("../", import.meta.url);
const core = await readFile(
  new URL("docs/core/school-schedule.js", root),
  "utf8",
);
const capture = await readFile(
  new URL("extension/capture-source.js", root),
  "utf8",
);
await mkdir(new URL("extension/core/", root), { recursive: true });
await writeFile(new URL("extension/core/school-schedule.js", root), core);
await writeFile(
  new URL("extension/capture.js", root),
  "// Generated by scripts/build-extension.mjs.\n(() => {\n" +
    core.replace(/^export /gm, "") +
    "\n" +
    capture +
    "\n})();\n",
);
